#!/usr/bin/env python3
"""Reader of the declared machine's system record platform/declared/x86sys.json (L5's, generated by gen_x86sys.py from the WDK 7.1 constants, Wine 9.0 and the declared CPU), format fnvnx-x86sys/2.
The record is the only place that holds the selectors, ring-3 interrupt vectors, CR4 bits and IOPL of the declared machine: this module holds no value of it.
A row is `{value, source}` or `{status: "undecided", why}`; get() returns the value of a decided row and raises Undecided(why) for an undecided one, for an absent row (the record lacks the key: its `why` says so) and for an absent record.
Location: the one explicit input fnvlift.inputs x86sys, set by the program that runs the prover (--x86sys PATH, configure() below): no environment variable and no default path."""
import os as _q_os, sys as _q_sys
_q_sys.path.insert(0, _q_os.path.join(_q_os.path.dirname(_q_os.path.abspath(__file__)), "..", "..", ".."))   # ports (`fnvnx` is ports/fnvnx -> fnv-nx): qualified imports of another root's modules (fnvnx.contract.X, fnvnx.verify.X)
import hashlib
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))
from fnvnx.lift.fnvlift import inputs  # noqa: E402
FORMAT = 'fnvnx-x86sys/2'


class Undecided(Exception):
    """the record gives no decided value for the row; str() is the blocker"""


def path():
    return inputs.get('x86sys')


def configure(p):
    """the --x86sys PATH of a prover program: sets the one input (fnvlift.inputs) and returns the file's sha256, which every record and queue header carries (a record made under another declared machine is stale)"""
    inputs.configure(x86sys=p)
    return sha()


def sha():
    with open(path(), 'rb') as fh: return hashlib.sha256(fh.read()).hexdigest()


def add_arg(ap):
    ap.add_argument('--x86sys', required=True, help='the declared x86 system record (platform/declared/x86sys.json); no default, no environment')


def load(p=None):
    p = p or path()
    if not os.path.exists(p):
        raise Undecided('record absent (%s)' % p)
    with open(p) as fh:
        r = json.load(fh)
    if r.get('format') != FORMAT:
        raise ValueError('%s: format %r, expected %s' % (p, r.get('format'), FORMAT))
    return r


def get(rec, *keys):
    """the decided value at rec[k0][k1]...; a row with `status: undecided` (at any level) raises Undecided(why)"""
    n = rec
    for i, k in enumerate(keys):
        if not isinstance(n, dict) or k not in n:
            raise Undecided('record has no row %s' % '.'.join(keys[:i + 1]))
        n = n[k]
        if isinstance(n, dict) and n.get('status') == 'undecided':
            raise Undecided('%s: %s' % ('.'.join(keys[:i + 1]), n.get('why', 'undecided')))
    if isinstance(n, dict) and 'value' in n:
        return n['value']
    return n


def cpl(rec):
    """the privilege level of user code: the RPL bits of the declared cs selector (SDM Vol. 3 3.4.2: CPL = CS.RPL)"""
    return get(rec, 'selectors', 'cs') & 3
